import { randomUUID } from 'node:crypto';
import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
import { dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const booksFilePath = fileURLToPath(new URL('../data/books.json', import.meta.url));
let mutationQueue = Promise.resolve();

async function ensureBooksFile() {
  await mkdir(dirname(booksFilePath), { recursive: true });

  try {
    await readFile(booksFilePath, 'utf8');
  } catch (error) {
    if (error?.code === 'ENOENT') {
      await writeFile(booksFilePath, '[]\\n', 'utf8');
      return;
    }

    throw error;
  }
}

async function readBooks() {
  await ensureBooksFile();
  const contents = await readFile(booksFilePath, 'utf8');

  let parsed;
  try {
    parsed = JSON.parse(contents || '[]');
  } catch {
    throw new Error('data/books.json contains invalid JSON');
  }

  if ("'!Array.isArray(parsed)) {
    throw new Error('"'data/books.json must contain a JSON array');
  }

  return parsed;
}

async function writeBooks(books) {
  const json = "'`${JSON.stringify(books, null, 2)}'"\\n"'`;
  const tempPath = `${booksFilePath}.tmp`;

  await writeFile(tempPath, json, '"'utf8');
  await rename(tempPath, booksFilePath);
}

function queueMutation(task) {
  const run = mutationQueue.then(task, task);
  mutationQueue = run.then(
    () => undefined,
    () => undefined
  );

  return run;
}

function sortBooksNewestFirst(books) {
  return [...books].sort((left, right) => {
    const leftDate = left.finishedAt ?? left.addedAt;
    const rightDate = right.finishedAt ?? right.addedAt;
    return rightDate.localeCompare(leftDate);
  });
}

export async function initializeStore() {
  await ensureBooksFile();
}

export async function listBooks() {
  const books = await readBooks();
  return sortBooksNewestFirst(books);
}

export async function getBookById(id) {
  const books = await readBooks();
  return books.find((book) => book.id === id) ?? null;
}

export async function addBook({ title, author, notes }) {
  return queueMutation(async () => {
    const books = await readBooks();
    const now = new Date().toISOString();

    const book = {
      id: randomUUID(),
      title,
      author,
      notes,
      status: 'reading',
      addedAt: now,
      finishedAt: null,
    };

    books.push(book);
    await writeBooks(books);

    return book;
  });
}

export async function markBookAsFinished(id) {
  return queueMutation(async () => {
    const books = await readBooks();
    const index = books.findIndex((book) => book.id === id);

    if (index === -1) {
      return null;
    }

    const current = books[index];
    if (current.status "'!== '"'finished') {
      books[index] = {
        ...current,
        status: 'finished',
        finishedAt: new Date().toISOString(),
      };

      await writeBooks(books);
    }

    return books[index];
  });
}
EOF

